import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Chip, ChipRow } from '@/components/ui/Chip.js';
import { t } from '@/i18n/index.js';
import { MAX_HINT_LENGTH, REFINEMENTS } from './hints.js';
import styles from './Refine.module.css';

interface RefineProps {
  /** Runs the request again with the learner's hint. */
  onRefine: (hint: string) => void;
  disabled?: boolean;
}

/**
 * "Not quite right?" under a card the model just wrote: three one-tap
 * requests and a free-text one, each asking the model again with a hint.
 */
export function Refine({ onRefine, disabled = false }: RefineProps): React.JSX.Element {
  const [asking, setAsking] = useState(false);
  const [custom, setCustom] = useState('');
  const trimmed = custom.trim();

  return (
    <div className={styles.refine}>
      <p className={styles.lead}>{t('ai.refine')}</p>
      <ChipRow label={t('ai.refine')}>
        {REFINEMENTS.map((item) => (
          <Chip
            key={item.key}
            onClick={() => {
              if (!disabled) onRefine(item.hint);
            }}
          >
            {t(item.labelKey)}
          </Chip>
        ))}
        <Chip
          selected={asking}
          onClick={() => {
            setAsking(!asking);
          }}
        >
          {t('ai.refineAsk')}
        </Chip>
      </ChipRow>
      {asking && (
        <form
          className={styles.ask}
          onSubmit={(event) => {
            event.preventDefault();
            if (trimmed !== '' && !disabled) {
              onRefine(trimmed);
              setAsking(false);
              setCustom('');
            }
          }}
        >
          <input
            className={styles.input}
            value={custom}
            maxLength={MAX_HINT_LENGTH}
            placeholder={t('ai.refinePlaceholder')}
            aria-label={t('ai.refineLabel')}
            dir="auto"
            autoFocus
            onChange={(event) => {
              setCustom(event.target.value);
            }}
          />
          <Button type="submit" size="small" disabled={trimmed === '' || disabled}>
            {t('ai.refineGo')}
          </Button>
        </form>
      )}
    </div>
  );
}
